"""Build the editorial pages around the retained scientific comparison workspace."""
from pathlib import Path
import json
import re
import shutil
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'web/dist'

def header(active):
    links=[('Home','index.html'),('Explore','explore.html'),('Compare','compare.html'),('Discover SPHEREx','discover.html'),('Methodology','methodology.html')]
    return '<a class="skip" href="#main">Skip to content</a><header class="site-header"><a class="wordmark" href="./index.html" aria-label="SKYSHIFT home"><svg viewBox="0 0 40 40" aria-hidden="true"><circle cx="20" cy="20" r="11"/><path d="M20 1v10m0 18v10M1 20h10m18 0h10M8 8l5 5m14 14 5 5"/></svg><span>SKYSHIFT<small>PROJECT MERCURY TEAM</small></span></a><button class="menu-toggle" aria-expanded="false" aria-controls="site-nav">Menu ☰</button><nav id="site-nav" aria-label="Main navigation">'+''.join(f'<a href="./{url}"'+(' aria-current="page"' if title==active else '')+f'>{title}</a>' for title,url in links)+'</nav><span class="local-label"><i></i> LOCAL OBSERVATORY</span></header>'

FOOTER='''<footer class="site-footer"><div><a class="wordmark" href="./index.html">SKYSHIFT</a><p>A Project Mercury Team application.<br>Independent student project. No NASA endorsement.</p></div><div><a href="./explore.html">Explore real observations ↗</a><a href="./methodology.html">Data, methods & credits ↗</a><a href="./guide.html">Reconstruct your evidence ↗</a></div><div><strong>Built to keep the evidence.</strong><p>Scientific approval: PENDING.<br>Local release 0.3 · Original science snapshot 0.2</p></div></footer>'''

def page(title,active,body,script='site.js'):
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#060b15"><meta name="description" content="Explore real SPHEREx infrared observations with exact source records and reproducible evidence. An independent Project Mercury Team application."><meta http-equiv="Content-Security-Policy" content="default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; img-src 'self' data: blob:; connect-src 'self'; object-src 'none'; base-uri 'none'; form-action 'none'"><title>SKYSHIFT — {title}</title><link rel="icon" href="./icon.svg"><link rel="stylesheet" href="./style.css"><link rel="stylesheet" href="./redesign.css"></head><body>{header(active)}{body}{FOOTER}<script type="module" src="./{script}"></script></body></html>'''

def build():
    assets=OUT/'assets'; assets.mkdir(exist_ok=True)
    source=ROOT/'research/redesign_assets'
    for name in ['spherex-vela.jpg','spherex-all-sky.jpg','spherex-spacecraft-concept.jpg','m101-hubble-context.jpg','assets.json']:
        shutil.copyfile(source/name, assets/name)
    shutil.copyfile(ROOT/'docs/evidence/provenance_audit_0.3.json',OUT/'data/provenance-audit.json')
    home='''<main id="main"><section class="hero"><img class="hero-image" src="./assets/spherex-vela.jpg" alt="Published SPHEREx infrared composite of the Vela Molecular Ridge, with a dense starfield and yellow gas-and-dust clouds"><div class="hero-shade"></div><div class="hero-content"><p class="eyebrow">A DIFFERENT LIGHT. A NEW PERSPECTIVE.</p><h1>Explore the<br>infrared sky<span>.</span></h1><p class="hero-intro">Meet the universe beyond visible light. Explore real observations from NASA’s SPHEREx telescope, look across dates, and keep the evidence behind every question.</p><div class="hero-actions"><a class="primary" href="./explore.html">Explore the sky <span>↗</span></a><a class="quiet-link" href="#how-it-works">How it works <span>↓</span></a></div></div><div class="image-credit"><strong>THE VELA MOLECULAR RIDGE · SPHEREx</strong><span>Official multi-wavelength composite · NASA/JPL-Caltech<br>Storytelling image; not the comparison dataset. <a href="./methodology.html#imagery">Image details ↗</a></span></div><div class="hero-index">01 / THE INFRARED UNIVERSE</div></section>
    <section class="mission-strip"><div><span class="eyebrow">THE MISSION</span><p>One sky.<br><strong>Many wavelengths.</strong></p></div><p>SPHEREx maps the sky in infrared light. SKYSHIFT brings a small, carefully documented selection of its observations into your browser.</p><a class="arrow-link" href="./discover.html">Meet SPHEREx <span>↗</span></a></section>
    <section class="editorial-section" id="how-it-works"><div class="section-heading"><div><p class="eyebrow">YOUR NEXT QUESTION STARTS HERE</p><h2>From looking<br>to investigating.</h2></div><p>No astronomy experience needed.<br>Start with a field. Let curiosity do the rest.</p></div><div class="steps"><article><span class="step-number">01</span><h3>Choose your corner<br>of the sky.</h3><p>Visit three curated regions. See what a real infrared exposure looks like, with its date and wavelength in view.</p><a href="./explore.html">Choose a region ↗</a></article><article><span class="step-number">02</span><h3>Look again.<br>With context.</h3><p>Compare the restricted M101 field across two dates. Shared controls keep the view fair; suitability limits stay visible.</p><a href="./compare.html">Open the comparison ↗</a></article><article><span class="step-number">03</span><h3>Keep the question.<br>Save the evidence.</h3><p>Mark a sky coordinate, write a note, and export the data references, settings and checks needed to reopen your view.</p><a href="./guide.html">See how evidence works ↗</a></article></div></section>
    <section class="editorial-section gallery-section"><div class="section-heading"><div><p class="eyebrow">OBSERVED. DOCUMENTED. READY TO EXPLORE.</p><h2>Find your field.</h2></div><p>Real, calibrated SPHEREx exposures.<br>A curated collection, not an all-sky viewer.</p></div><div class="field-gallery" data-gallery></div><p class="caption">Previews show single-band SPHEREx data with an asinh brightness stretch. They are not visible-light photographs. Temporal comparison requires separate checks.</p></section>
    <section class="trust-feature"><div><p class="eyebrow">CURIOSITY DESERVES A SOURCE</p><h2>Every pixel.<br>A path back.</h2><p>From NASA/IPAC’s archive to the image on your screen, source identities and processing records stay attached. Inspect the audit, download the evidence, and reproduce the result.</p><a class="primary" href="./methodology.html#audit">Follow the data ↗</a></div><div class="provenance-path"><span>01 <strong>NASA/IPAC IRSA archive</strong></span><i>↓</i><span>02 <strong>Original calibrated FITS</strong></span><i>↓</i><span>03 <strong>Validated preparation & masks</strong></span><i>↓</i><span>04 <strong>Your view & evidence record</strong></span><p>Authenticity checked. Scientific approval remains pending.</p></div></section></main>'''
    (OUT/'index.html').write_text(page('Explore the infrared sky','Home',home),encoding='utf-8')
    explore='''<main id="main" class="explore-page"><section class="page-intro"><p class="eyebrow">YOUR WINDOW INTO THE INFRARED</p><h1>A sky worth<br>looking closer at.</h1><p>Choose a region. Explore a real exposure. Every view includes its date, spectral context, and original source.</p></section><div class="field-gallery compact" data-gallery></div><section id="explorer" class="explorer"><div class="explorer-title"><div><p class="eyebrow">SINGLE-OBSERVATION EXPLORER</p><h2 id="explore-title">Loading the archive selection…</h2><p id="explore-description"></p></div><a id="compare-link" class="primary" href="./compare.html">Compare the restricted field ↗</a></div><div id="explore-error" role="alert" hidden></div><div class="explore-layout"><div><div class="explore-toolbar"><div id="observation-timeline" class="timeline" role="group" aria-label="Available individual exposures"></div><div class="zoom-controls"><button id="explore-minus" aria-label="Zoom out">−</button><output id="explore-zoom">1.0×</output><button id="explore-plus" aria-label="Zoom in">+</button><button id="explore-reset">Reset</button></div></div><div class="explore-canvas-wrap"><canvas id="explore-canvas" tabindex="0" aria-label="Real SPHEREx single-observation field, drag to pan"></canvas><span class="canvas-stamp">REAL SPHEREx DATA · SINGLE EXPOSURE</span></div><p class="coordinate-bar" id="explore-coordinate">Move over the image to read original prepared pixel values.</p><div class="visual-controls"><label>Brightness stretch<select id="explore-stretch"><option value="asinh">Asinh · reveal faint structure</option><option value="log">Log · display intensity</option><option value="linear">Linear</option></select></label><label>Single-band palette<select id="explore-palette"><option value="grayscale">Grayscale</option><option value="ember">Ember · false color</option><option value="ice">Ice · false color</option></select></label><label>Display sampling<select id="explore-interpolation"><option value="smooth">Smooth interpolation</option><option value="nearest">Inspect prepared pixels</option></select></label><label>Contrast<input id="explore-contrast" type="range" min="0.5" max="2" step="0.05" value="1"></label></div><p class="caption">Drag to pan · + / − to zoom · North up, east left. Smooth interpolation changes display only. No invented detail, sharpening or gap filling.</p></div><aside class="observation-card"><p class="eyebrow">WHAT AM I LOOKING AT?</p><h3>Infrared light,<br>one exposure.</h3><dl id="explore-facts"></dl><div class="status-callout" id="explore-status"></div><details><summary>Source, calibration & checksums</summary><div id="explore-source"></div></details><button id="export-context" class="outline full">↓ Export this view record</button><p class="caption">A JSON record of this single exposure, display settings, viewport, pixel hashes and original archive references. This is not a temporal-comparison packet.</p></aside></div></section><section class="sky-context editorial-section"><div><p class="eyebrow">FIND YOUR BEARINGS</p><h2>Three places.<br>One celestial sphere.</h2><p>Right ascension and declination locate a field on the sky, like longitude and latitude. This schematic marks only our available regions; it is not an image of the sky.</p></div><div><svg id="sky-map" viewBox="0 0 720 260" role="img" aria-label="Schematic right ascension and declination map marking M101, M67 and NGC 188"></svg><p class="caption">ICRS coordinate schematic · right ascension increases to the left · no star-density information</p></div></section></main>'''
    (OUT/'explore.html').write_text(page('Explore real observations','Explore',explore,'explore.js'),encoding='utf-8')
    # Keep the existing evidence/annotation machinery and its DOM contract intact.
    original=ROOT/'tools/templates/comparison_core_0.2.html'
    old=original.read_text(encoding='utf-8')
    content=old[old.index('  <main>'):old.index('  <footer>')]
    content=content.replace('<main>','<main id="main" class="compare-page">',1)
    start=content.index('    <section class="intro">');end=content.index('    <div class="review-banner"')
    content=content[:start]+'''<section class="compare-intro"><div><p class="eyebrow">LOOK TWICE. KEEP THE CONTEXT.</p><h1>One field. Two moments.</h1><p>Explore a small part of M101 on two dates. Mark a question and save a reproducible evidence record.</p></div><div class="field-selector"><label for="field">COMPARISON FIELD</label><select id="field"><option>M101 · restricted review field</option></select><span id="field-position"></span><a href="./explore.html?field=m101#explorer">See the larger single-exposure context ↗</a></div></section><div class="comparison-guide"><span><b>1</b> Look at A and B</span><span><b>2</b> Switch, zoom, inspect</span><span><b>3</b> Mark a question & export</span></div><p class="resolution-explainer"><strong>24 × 24 prepared pixels · 6.15 arcsec/pixel · 2.4 arcmin field.</strong> A larger region failed our wavelength screen. Smooth display adds no measured detail. <a href="./methodology.html#resolution">Why this field is small ↗</a></p>'''+content[end:]
    content=content.replace('<button id="single-mode" aria-pressed="false">A / B switch</button>', '<button id="single-mode" aria-pressed="false">A / B switch</button><button id="overlay-mode" aria-pressed="false">Wipe overlay</button>')
    content=content.replace('<div class="toolbar">','<div id="comparison-timeline" class="comparison-timeline" aria-label="Both observation start times"></div><div class="toolbar">',1)
    content=content.replace('<div class="viewer-layout">','<div id="wipe-controls" class="wipe-controls" hidden><label>Overlay split: A left / B right <input id="wipe" type="range" min="0" max="100" value="50"></label><span>Same grid and scale · split is visual only</span></div><div class="viewer-layout">',1)
    content=content.replace('<details class="display-settings">','''<div class="visual-controls"><label>Brightness stretch<select id="visual-stretch"><option value="asinh">Asinh</option><option value="log">Log · display intensity</option><option value="linear">Linear</option></select></label><label>Single-band palette<select id="visual-palette"><option value="grayscale">Grayscale</option><option value="ember">Ember · false color</option><option value="ice">Ice · false color</option></select></label><label>Display sampling<select id="visual-interpolation"><option value="smooth">Smooth interpolation</option><option value="nearest">Inspect prepared pixels</option></select></label></div><p class="caption">Shared between both dates. False color represents intensity in one band, not visible color. Log uses log(1 + scaled display intensity), with negative measured flux retained unchanged.</p><details class="display-settings">''',1)
    dialog=old[old.index('  <dialog'):old.index('  <script')]
    (OUT/'compare.html').write_text(page('Compare two observations','Compare',content+dialog,'app.js'),encoding='utf-8')
    discover='''<main id="main"><section class="discover-hero"><img src="./assets/spherex-all-sky.jpg" alt="Official SPHEREx first all-sky infrared composite, with the Milky Way across an oval sky map"><div><p class="eyebrow">DISCOVER SPHEREx</p><h1>Beyond what<br>our eyes can see.</h1><p>Infrared light reveals a different view of stars, dust and galaxies. SPHEREx surveys the sky across 102 spectral channels, spanning roughly 0.75–5 micrometers.</p></div></section><p class="image-caption">Official first all-sky infrared composite · NASA/JPL-Caltech · Published December 2025. Spatial resolution heavily reduced for this full-sky presentation. This is a storytelling image, not an interactive all-sky dataset.</p><section class="editorial-section learn-grid"><article><p class="eyebrow">LIGHT AS INFORMATION</p><h2>A color can<br>be a clue.</h2><p>Wavelength describes a kind of light. Different wavelengths can emphasize different objects and materials. Scientists use this information to study the history of galaxies, water and organic molecules, and the early universe.</p><p>These questions motivate the mission. SKYSHIFT does not identify molecules or make discoveries automatically.</p><a href="https://science.nasa.gov/mission/spherex/" target="_blank" rel="noreferrer">Read NASA’s mission overview ↗</a></article><article><p class="eyebrow">READ THE IMAGE CAREFULLY</p><h2>A fair comparison<br>takes more than dates.</h2><p>SPHEREx’s filter samples different wavelengths across an exposure. A pixel’s location affects what light it records. Two pictures taken on different dates can differ because of wavelength, image blur, background or instrumental artifacts.</p><p>SKYSHIFT checks spectral overlap and registration before offering a provisional comparison. A possible difference is a question for review, not proof of change.</p><a href="./methodology.html">Understand the checks ↗</a></article></section><section class="mission-feature"><img src="./assets/spherex-spacecraft-concept.jpg" alt="Artist’s concept of the SPHEREx spacecraft above Earth"><div><p class="eyebrow">THE OBSERVATORY</p><h2>A mission.<br>A wider perspective.</h2><p>SKYSHIFT uses calibrated observations distributed by NASA/IPAC IRSA. Our curated explorer shows individual detector cutouts, with quality masks and their spectral context preserved.</p><p class="caption">Spacecraft artist’s concept · NASA/JPL-Caltech. Illustration, not an astronomical measurement.</p><a class="primary" href="./explore.html">Start exploring ↗</a></div></section></main>'''
    (OUT/'discover.html').write_text(page('Discover SPHEREx','Discover SPHEREx',discover),encoding='utf-8')
    methods='''<main id="main" class="methods-page"><section class="page-intro"><p class="eyebrow">PROJECT MERCURY TEAM / METHODS & SOURCES</p><h1>Wonder, with<br>the evidence attached.</h1><p>SKYSHIFT is an independent student application for inspecting real SPHEREx observations. Authenticity, engineering validation, and scientific approval are separate questions.</p></section><section id="audit" class="editorial-section"><div class="section-heading"><div><p class="eyebrow">ARCHIVE → FITS → PREPARATION → BROWSER</p><h2>Follow the data.</h2></div><a class="outline" href="./data/provenance-audit.json" download>↓ Download the complete audit</a></div><div class="audit-summary" id="audit-summary">Loading the recorded provenance audit…</div><p>The audit independently downloaded the original cutouts and calibration files again, checked archive exposure identities and times, and compared all ten browser arrays against prepared FITS and a fresh reconstruction. The historical public release was also checked; local execution now has no dependency on that host.</p><details><summary>Inspect the complete machine-readable audit</summary><pre id="audit-json"></pre></details><a class="arrow-link" href="./compare.html#evidence">Inspect observations, sources and diagnostics in the workspace ↗</a></section>
    <section id="resolution" class="editorial-section"><p class="eyebrow">WHY DOES THE COMPARISON HAVE 24 × 24 PIXELS?</p><h2>Small for a reason.<br>Larger where it is honest.</h2><div class="learn-grid"><div><p>The active detector calibration covers 2040 × 2040 pixels. The downloaded M101 native contexts have 176 × 116 and 176 × 137 pixels (width × height); a cutout can be clipped by the detector edge. Neither is the size of the whole instrument.</p><p>The comparison grid is a separate, north-up 24 × 24 grid at 6.15 arcseconds per pixel, covering 2.4 arcminutes. A 0.12° test failed the spectral criterion; even a 0.06° test exceeded it. A 0.04° region passed the provisional engineering screen.</p></div><div><p>We keep that threshold: every common pixel must have wavelength separation no larger than 0.25 of the smaller local bandwidth. The explorer’s larger contexts are individual exposures, not approved wider temporal comparisons.</p><p>Linear, asinh and log display stretches reveal different brightness levels. Single-band false color and smooth display interpolation change presentation only. Hover reads the actual nearest prepared pixel. No super-resolution, sharpening, inpainting or artificial astronomical detail is used.</p></div></div></section>
    <section class="editorial-section"><p class="eyebrow">WHAT THE CHECKS ESTABLISH</p><h2>Evidence has boundaries.</h2><div class="steps"><article><span class="step-number">01</span><h3>Authentic inputs</h3><p>Identifiable QR2 calibrated FITS, exact source URLs, SHA-256 hashes, release-aware masks, full CWAVE/CBAND spectral calibration, and per-pixel provenance.</p></article><article><span class="step-number">02</span><h3>Engineering screens</h3><p>13 independently fitted Gaia references: median inter-epoch residual 0.312 arcsec, 95th percentile 2.007 arcsec. Common usable support: 94.4%. These are measured residuals, not absolute-position precision.</p></article><article><span class="step-number">03</span><h3>Scientific approval: pending</h3><p>No completed human internal technical review or qualified external scientific approval is claimed. Questions remain about full response equivalence, calibration UUID associations, PSF differences and acceptable interpretation.</p></article></div><div class="status-callout">No confirmed motion, brightness variability, source identification, or discovery. No PSF matching, background subtraction, calibrated difference image or significance map. Resampled pixel covariance prevents naïve precision claims.</div><p>The saved review packet retains rejected wider fields, an initial insufficient-reference test, the corrected reference-membership audit, uncertainties, reproducible code and separate blank human-review records. M67 and NGC 188 tested wider pairs remain incompatible. No three-date comparison is supported.</p><a href="./guide.html">Reproduction and review guide ↗</a></section>
    <section id="imagery" class="editorial-section"><p class="eyebrow">IMAGE CREDITS & CATEGORIES</p><h2>Beautiful images.<br>Explicit identities.</h2><div id="imagery-credits" class="credits-grid"></div><p>Official mission composites combine wavelengths and use published color assignments. Our scientific canvases use single-band calibrated surface brightness. These categories are never interchangeable. NASA logos and insignia are not used. <a href="https://www.nasa.gov/nasa-brand-center/images-and-media/" target="_blank" rel="noreferrer">NASA media guidance ↗</a></p><a href="./assets/assets.json" download>Download image source records and hashes ↗</a></section><section class="editorial-section"><p class="eyebrow">YOUR COMPUTER. YOUR RECORDS.</p><h2>Independent by design.</h2><p>All viewing, annotations, display controls, source records and evidence exports run locally. Assets and curated data are served by the local production server. Nothing is sent to a hosting service. New archive retrieval and external links require internet access; numerical reconstruction uses Python and can run offline from the full review packet. Export notes before closing a tab.</p><p>To run: <code>start_skyshift.bat</code> from your project folder. To stop: close the server with Ctrl+C. The same ordinary static assets can later be hosted under your own domain.</p></section></main>'''
    (OUT/'methodology.html').write_text(page('Data, methods and sources','Methodology',methods),encoding='utf-8')
    guide=(OUT/'guide.html').read_text(encoding='utf-8').replace('href="./"','href="./compare.html"')
    guide=guide.replace('</head>','<link rel="stylesheet" href="./redesign.css"></head>') if 'redesign.css' not in guide else guide
    guide=re.sub(r'<h2>Display extensions in release 0.3</h2><p>.*?</p>','',guide)
    guide=guide.replace('grayscale settings','intensity settings and optional display extension').replace('<h2>Choose the appropriate evidence packet</h2>','<h2>Display extensions in release 0.3</h2><p>Browser exports add a hashed visualization.json record for log display, palette, interpolation and wipe position. Browser reopen restores it after validation. The scientific manifest retains its original schema and numerical reconstruction remains unchanged. Python reconstructs arrays and the core viewport; the browser restores the optional visualization extension. Log applies log(1 + 100 × normalized display intensity), not a logarithm of measured flux.</p><h2>Choose the appropriate evidence packet</h2>')
    (OUT/'guide.html').write_text(guide,encoding='utf-8')

if __name__=='__main__': build()
